#include <stdexcept>
juce::AudioProcessorEditor* NovaProcessor::createEditor(){return new NovaEditor(*this);}
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
void pump(int ms=50){juce::MessageManager::getInstance()->runDispatchLoopUntil(ms);}
juce::Button* button(juce::Component& root,const juce::String& name){if(auto* b=dynamic_cast<juce::Button*>(&root))if(b->getButtonText()==name&&b->isShowing())return b;for(int i=0;i<root.getNumChildComponents();++i)if(auto* b=button(*root.getChildComponent(i),name))return b;return nullptr;}
void click(juce::Component& root,const juce::String& name){pump(80);auto* b=button(root,name);if(!b)throw std::runtime_error("button not showing: "+name.toStdString());if(!b->isEnabled())throw std::runtime_error("button disabled: "+name.toStdString());b->triggerClick();pump();}
void snapshot(juce::Component& c,const juce::File& dir,const juce::String& name){pump(250);juce::FileOutputStream stream(dir.getChildFile(name+".png"));stream.setPosition(0);stream.truncate();juce::PNGImageFormat format;check(format.writeImageToStream(c.createComponentSnapshot(c.getLocalBounds()),stream),"PNG snapshot");}
template<class T>T* named(juce::Component& root,const juce::String& name){if(auto* c=dynamic_cast<T*>(&root))if(c->getName()==name)return c;for(int i=0;i<root.getNumChildComponents();++i)if(auto* c=named<T>(*root.getChildComponent(i),name))return c;return nullptr;}
void openEdit(NovaEditor& e,const juce::String& tab){if(!e.isEditing())click(e,"Editar sonido");click(e,tab);}
